import{_ as n,a as t,b as s,c as o,d as p}from"./chunks/wp13-claude-easter-04.BzNYNjg5.js";import{_ as i,C as l,o as c,c as r,E as d,a2 as u}from"./chunks/framework.Cm6XCzck.js";const h="/joinwell52/assets/covers/wp13-codeflowmu-fact-check-process-zh.svg",v=JSON.parse('{"title":"一个 Agent 说“完成了”，团队为什么没放行？","description":"","frontmatter":{"title":"一个 Agent 说“完成了”，团队为什么没放行？","date":"2026-08-06","column":"open-source-engineering","category":"daily","summary":"这不是模型层面的幻觉检测，而是协议与组织结构层面的治理：FCoP 外化事实，CodeFlowMu 运行角色，PM 依据证据拒绝无证据的“完成”。","cover":"/assets/covers/daily-2026-08-06-codeflowmu-multi-agent-fact-checking-cover-v2.jpg","item_id":"WP13-CODEFLOWMU-FACT-CHECK","lifecycle":"Published","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep"},"headers":[],"relativePath":"zh/engineering/2026-08-06-codeflowmu-multi-agent-fact-checking.md","filePath":"zh/engineering/2026-08-06-codeflowmu-multi-agent-fact-checking.md","lastUpdated":1787407830000}'),g={name:"zh/engineering/2026-08-06-codeflowmu-multi-agent-fact-checking.md"};function m(b,e,P,f,A,k){const a=l("ArticleCover");return c(),r("div",null,[d(a,{image:"/assets/covers/daily-2026-08-06-codeflowmu-multi-agent-fact-checking-cover-v2.jpg",kicker:"开源工程 · CodeFlowMu 应用案例",title:"一个 Agent 说‘完成了’，团队为什么没放行？",summary:"这不是模型层面的幻觉检测，而是协议与组织结构层面的治理：FCoP 提供事实轨道，CodeFlowMu 运行角色，PM 依据证据说‘不’。",version:"WP-13",status:"Field Case · 2026-08-06",languageHref:"/en/engineering/2026-08-06-codeflowmu-multi-agent-fact-checking",languageLabel:"English"}),e[0]||(e[0]=u('<h1 id="一个-agent-说-完成了-团队为什么没放行" tabindex="-1">一个 Agent 说“完成了”，团队为什么没放行？ <a class="header-anchor" href="#一个-agent-说-完成了-团队为什么没放行" aria-label="Permalink to &quot;一个 Agent 说“完成了”，团队为什么没放行？&quot;">​</a></h1><p><em>CodeFlowMu 多 Agent 防幻觉实战</em></p><p><strong>这不是模型层面的“幻觉检测”，而是协议与组织结构层面的治理：FCoP 作为 Agent POSIX 外化事实，CodeFlowMu 作为应用与 Runtime 运行角色，PM 依据证据决定是否放行。</strong></p><p>下午 1 点 06 分，一个 DEV 子执行返回了 <code>completed</code>。</p><p>它给出的总结很完整：实现思路、测试命令、提交说明、剩余风险，看起来像一份可以直接交给 PM 的工作回执。</p><p>但同一份原始事件里，还埋着三句话：</p><blockquote><p>The shell command returned no exit status, so its result is unknown — do not assume it ran or succeeded.</p><p>Test results summary: Unconfirmed in this session.</p><p>Commit SHA: Not available here.</p></blockquote><p><strong>一边是“完成了”，另一边是“无法确认是否执行成功”。</strong></p><p>如果 PM 接受这句“完成”，QA 就会收到一个尚未形成的交付；如果 QA 再只复述 DEV 的结论，任务可能继续进入验收、关闭甚至发布。到了那一步，幻觉就不再只是模型的一句话，而会变成任务状态、报告、提交记录和产品决策。</p><p>WP-13 没有这样结束。</p><p>PM 没有放行。</p><h2 id="幻觉发生在一个-agent-里-事故发生在团队把它当真时" tabindex="-1">幻觉发生在一个 Agent 里，事故发生在团队把它当真时 <a class="header-anchor" href="#幻觉发生在一个-agent-里-事故发生在团队把它当真时" aria-label="Permalink to &quot;幻觉发生在一个 Agent 里，事故发生在团队把它当真时&quot;">​</a></h2><p>我们经常把“防幻觉”理解成让模型更聪明：换更大的模型、补更长的提示词、再加一个自我反思步骤。</p><p>这些方法有价值，但它们仍然把希望寄托在同一个主体身上：<strong>让说错话的人自己证明自己没有说错。</strong></p><p>CodeFlowMu 的做法不同。多 Agent 不是几个模型轮流发言，也不是让三个模型投票，而是一支有岗位、有事实来源、有权限边界和交接关系的团队：</p><ul><li>DEV 负责实现，可以犯错，也可能在工具异常时产生错误判断；</li><li>PM 负责判断交付事实是否满足任务合同，不能把 DEV 的自述当成证据；</li><li>QA 负责以分离角色重新验证，不能只复述 DEV 报告；</li><li>Runtime 负责唤醒、调度、恢复、界面和实时操作流，但不替 PM 作业务裁决。</li></ul><p>真正有效的机制不是“保证 DEV 永远不幻觉”，而是：</p><blockquote><p><strong>即使某个 Agent 产生幻觉，其他角色也能依靠外部事实，阻止它获得系统权威。</strong></p></blockquote><h2 id="现场-上部是-pm-的事实判断-底部是-agent-的实时操作流" tabindex="-1">现场：上部是 PM 的事实判断，底部是 Agent 的实时操作流 <a class="header-anchor" href="#现场-上部是-pm-的事实判断-底部是-agent-的实时操作流" aria-label="Permalink to &quot;现场：上部是 PM 的事实判断，底部是 Agent 的实时操作流&quot;">​</a></h2><p>下面这张图不是后期制作的流程示意，而是当时 CodeFlowMu 业务系统中的真实现场。</p><p>上部是 PM 与任务事实；底部保留了 Agent 的实时操作流与可见思考摘要。图中最重要的一句话不是 DEV 的自述，而是 PM 已经作出的判断：</p><blockquote><p><strong>子代理自称完成但产物不全--不能当真完成。</strong></p></blockquote><p>这不是后加的旁白，也不是文章作者的总结，而是 PM 在核对磁盘、Git、REPORT 和任务状态后给出的业务裁决。它把 <code>completed</code> 从一句容易被接受的语言声明，重新降回“证据不足，不能放行”。</p><p><img src="'+n+'" alt="CodeFlowMu 现场：PM 事实复核与 Agent 实时操作流"></p><p>13:08 左右，PM 看到的事实是：正式 DEV REPORT 不存在；Git HEAD 仍属于前一个 WP；任务要求的测试文件尚未完整落盘；Shell 多次返回 <code>no exit status</code>；子执行自己也承认测试未确认、SHA 不可得。</p><p>于是 PM 作出判断：</p><p><strong>不派 QA，不收口，不新建一个重复任务，继续原任务。</strong></p><h2 id="五个角色动作-把一句-完成了-变成可验证的交付" tabindex="-1">五个角色动作，把一句“完成了”变成可验证的交付 <a class="header-anchor" href="#五个角色动作-把一句-完成了-变成可验证的交付" aria-label="Permalink to &quot;五个角色动作，把一句“完成了”变成可验证的交付&quot;">​</a></h2><p><img src="'+h+`" alt="WP-13 五阶段多 Agent 事实复核"></p><h3 id="第一幕-dev-的工具通道失去确定性" tabindex="-1">第一幕：DEV 的工具通道失去确定性 <a class="header-anchor" href="#第一幕-dev-的工具通道失去确定性" aria-label="Permalink to &quot;第一幕：DEV 的工具通道失去确定性&quot;">​</a></h3><p>DEV 已经完成了部分实现，但 Edit、Shell、Read 等工具连续返回异常状态。最关键的不是“工具报错”，而是工具无法提供可靠的退出状态。</p><p>在软件工程中，<code>unknown</code> 与 <code>success</code> 之间有一条不能跨越的线。没有退出状态，就不能证明命令执行了；没有输出，就不能证明测试通过了；没有 commit，就不能证明代码已经形成可追踪交付。</p><h3 id="第二幕-子执行生成了一个很像完成报告的答案" tabindex="-1">第二幕：子执行生成了一个很像完成报告的答案 <a class="header-anchor" href="#第二幕-子执行生成了一个很像完成报告的答案" aria-label="Permalink to &quot;第二幕：子执行生成了一个很像完成报告的答案&quot;">​</a></h3><p>子执行并没有故意造假。它尝试继续工作，也给出了完整的技术计划。但当工具通道无法确认结果时，它仍把过程组织成了一段带“完成意味”的总结。</p><p>这是大模型最自然、也最危险的能力之一：<strong>把零散、缺失、互相冲突的信息组织成一段连贯叙事。</strong></p><p>语言连贯，不代表事实闭合。</p><h3 id="第三幕-pm-拒绝让叙事获得业务权威" tabindex="-1">第三幕：PM 拒绝让叙事获得业务权威 <a class="header-anchor" href="#第三幕-pm-拒绝让叙事获得业务权威" aria-label="Permalink to &quot;第三幕：PM 拒绝让叙事获得业务权威&quot;">​</a></h3><p>PM 没有再问一遍“你确定吗”。同一个 Agent 的再次确认，仍然只是另一条语言声明。</p><p>工程上更关键的问题是：PM 到底“怎么”查到这些事实？这是 prompt 让 PM 自觉检查，还是 Runtime 在放行前强制执行一组非 LLM 检查？</p><p>从 WP-13 证据包能够确认的实际链路是：</p><ol><li>Runtime 记录并展示子执行结束事件，同时保留 <code>no exit status</code>、测试未确认和 SHA 不可得等异常事实；</li><li>Runtime 维持原任务身份，并把该任务继续交给 PM 处理；</li><li>PM Agent 在自己的执行会话中主动读取任务、生命周期位置、REPORT、磁盘文件、Git 状态和 Runtime 事件；</li><li>文件是否存在、HEAD 指向哪里、退出状态是否为空，属于确定性观察；</li><li>这些事实是否满足 WP-13 的完成合同，以及应继续、返工还是派 QA，由 PM 作业务裁决。</li></ol><p>因此，本文不能把现场写成“FCoP 自动识别了幻觉”，也不能声称当时已经有一个全局硬编码的 <code>collect_evidence()</code> 门禁替 PM reject。更准确的表达是：</p><blockquote><p><strong>Runtime 保存并暴露事实；PM 按岗位职责和任务合同主动核验；业务放行权仍属于 PM。</strong></p></blockquote><h4 id="pm-核验的对象与可复现检查" tabindex="-1">PM 核验的对象与可复现检查 <a class="header-anchor" href="#pm-核验的对象与可复现检查" aria-label="Permalink to &quot;PM 核验的对象与可复现检查&quot;">​</a></h4><p>下表中的命令是可复现的等价检查，用来说明事实来自哪里；它们不是声称 PM 当时逐字执行了同一组命令。</p><table tabindex="0"><thead><tr><th>要核验的事实</th><th>可复查的数据源或等价检查</th><th>13:08 左右的结果</th></tr></thead><tbody><tr><td>任务当前状态</td><td>在 <code>fcop/_lifecycle/{inbox,active,review,done}/</code> 定位 <code>TASK-20260805-019</code></td><td>仍在 <code>active</code></td></tr><tr><td>DEV 是否正式交付</td><td>查找 <code>fcop/reports/REPORT-*-DEV-to-PM.md</code> 并核对任务引用</td><td>未找到对应 REPORT</td></tr><tr><td>是否形成 WP-13 提交</td><td><code>git rev-parse HEAD</code>、<code>git show --stat HEAD</code>，再核对 WP-13 路径</td><td>HEAD 仍属于前一个 WP</td></tr><tr><td>必需文件是否落盘</td><td>按 TASK 中要求的 WP-13 文件和测试路径执行 <code>stat/glob</code></td><td>不完整</td></tr><tr><td>命令和测试是否可确认</td><td>读取 Runtime 原始事件、Shell 退出状态和测试输出</td><td>至少一个相关 Shell 事件的 <code>exit_status = null</code>，结果为 <code>unknown</code></td></tr></tbody></table><p><code>task_bucket</code> 不是完成证据本身，而是生命周期一致性约束。对这次 pre-QA 核验，PM 预期任务仍在 <code>active</code>；如果它已经被提前挪到 <code>review</code>、<code>done</code> 或 <code>archive</code>，这本身就是状态漂移，应先阻塞并核对，而不能继续放行。</p><p>把现场机制抽象成伪代码，大致是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>on_subexecution_finished(event):</span></span>
<span class="line"><span>    runtime.append(event)</span></span>
<span class="line"><span>    # completed 与 exit_status=null 被保留为两个不同事实</span></span>
<span class="line"><span>    runtime.surface_to_pm(event.task_id)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>PM.review_completion(task_id):</span></span>
<span class="line"><span>    contract = read_task_contract(task_id)</span></span>
<span class="line"><span>    facts = {</span></span>
<span class="line"><span>        task_bucket: locate_task(task_id),</span></span>
<span class="line"><span>        report: find_dev_report(task_id),</span></span>
<span class="line"><span>        git_head: git_rev_parse(&quot;HEAD&quot;),</span></span>
<span class="line"><span>        required_files: stat(contract.required_files),</span></span>
<span class="line"><span>        command_results: read_runtime_events(task_id)</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    unexpected_bucket = facts.task_bucket != &quot;active&quot;</span></span>
<span class="line"><span>    shell_events = [</span></span>
<span class="line"><span>        e for e in facts.command_results</span></span>
<span class="line"><span>        if e.kind == &quot;shell&quot;</span></span>
<span class="line"><span>    ]</span></span>
<span class="line"><span>    any_unresolved = any(</span></span>
<span class="line"><span>        e.exit_status is null</span></span>
<span class="line"><span>        for e in shell_events</span></span>
<span class="line"><span>    )</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    if unexpected_bucket</span></span>
<span class="line"><span>       or facts.report.missing</span></span>
<span class="line"><span>       or not commit_matches(contract, facts.git_head)</span></span>
<span class="line"><span>       or not facts.required_files.complete</span></span>
<span class="line"><span>       or any_unresolved:</span></span>
<span class="line"><span>        PM.decision = &quot;evidence_incomplete&quot;</span></span>
<span class="line"><span>        dispatch_QA = false</span></span>
<span class="line"><span>        continue_same_task = true</span></span>
<span class="line"><span>    else:</span></span>
<span class="line"><span>        dispatch_QA = true</span></span></code></pre></div><p>这段伪代码是对现场机制的工程抽象，<strong>不是声称仓库里已经存在一个同名硬门禁</strong>。后续 Runtime 可以把 <code>report_missing</code>、<code>commit_unreachable</code>、<code>evidence_incomplete</code> 预计算成确定性诊断，但继续、返工或接受仍应由具备职责的角色裁决。</p><p>下面是<strong>归一化证据摘要</strong>。字段来自证据包中的原始事件和 PM 核验结果，但排版不是 Runtime JSONL 的逐字复制：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>13:06  subexecution.status = completed</span></span>
<span class="line"><span>       shell_events.any(exit_status = null) = true</span></span>
<span class="line"><span>       tests = unconfirmed</span></span>
<span class="line"><span>       commit_sha = unavailable</span></span>
<span class="line"><span></span></span>
<span class="line"><span>13:08  task.bucket = active</span></span>
<span class="line"><span>       expected_bucket = active</span></span>
<span class="line"><span>       dev_report = missing</span></span>
<span class="line"><span>       wp13_commit = missing</span></span>
<span class="line"><span>       required_test_files = incomplete</span></span>
<span class="line"><span>       pm_decision = evidence_incomplete</span></span>
<span class="line"><span>       next = continue TASK-20260805-019; do not dispatch QA</span></span></code></pre></div><p>PM 发现完成合同没有闭合，于是拒绝派 QA，并保留原任务继续执行。这里没有神奇的“真假分类器”，只有一个不同职责的角色根据外部事实作出有限、可解释的业务判断。</p><h3 id="第四幕-dev-在原任务上完成真实交付" tabindex="-1">第四幕：DEV 在原任务上完成真实交付 <a class="header-anchor" href="#第四幕-dev-在原任务上完成真实交付" aria-label="Permalink to &quot;第四幕：DEV 在原任务上完成真实交付&quot;">​</a></h3><p>工具恢复后，DEV 继续的是同一个 <code>TASK-20260805-019</code>，而不是复制一个新任务掩盖异常。</p><p>随后真实产物出现了：</p><ul><li>commit：<code>609571ddb22d1fbb2bfb5e54692c07beeef4cf23</code>；</li><li>12 个 WP-13 文件；</li><li><code>1230 insertions / 452 deletions</code>；</li><li>正式 <code>REPORT-20260805-037-DEV-to-PM.md</code>；</li><li>observation 测试 3/3 PASS；</li><li>activity-buffer + project-graph 测试 10/10 PASS；</li><li>root-fault + log-center 回归 14/14 PASS；</li><li>runtime typecheck exit 0；</li><li>未启用生产 Active；</li><li>未修改 TaskDispatcher 的真实投递路径。</li></ul><p>到这里，“完成”才第一次不再依赖 DEV 的语言表达。</p><h3 id="第五幕-qa-不相信-dev-也不相信-pm-只相信重新验证的结果" tabindex="-1">第五幕：QA 不相信 DEV，也不相信 PM，只相信重新验证的结果 <a class="header-anchor" href="#第五幕-qa-不相信-dev-也不相信-pm-只相信重新验证的结果" aria-label="Permalink to &quot;第五幕：QA 不相信 DEV，也不相信 PM，只相信重新验证的结果&quot;">​</a></h3><p>13:09，PM 在核验 REPORT 和 commit 后，才派出 QA 任务 <code>TASK-20260805-020</code>。</p><p>QA 作为分离角色，重新执行测试与边界检查。13:11，实时操作流里出现了一句真正有证据支持的话：</p><blockquote><p>测试全部通过，27/27。DEV 报告的 3+10+14=27 与实际结果一致。</p></blockquote><p>最终 QA 结果包括：</p><ul><li>27/27 测试通过；</li><li>typecheck exit 0；</li><li><code>git diff --check</code> exit 0；</li><li>commit 未包含 TaskDispatcher；</li><li><code>production_active</code> 保持 false。</li></ul><p>这是<strong>角色分离 QA 验证</strong>，不是外部第三方审计。但它已经打破了“执行者自证、自批、自关闭”的单点结构。</p><h2 id="fcop-协议-让-agent-会说-不" tabindex="-1">FCoP 协议，让 Agent 会说“不” <a class="header-anchor" href="#fcop-协议-让-agent-会说-不" aria-label="Permalink to &quot;FCoP 协议，让 Agent 会说“不”&quot;">​</a></h2><p>大模型最不缺的是继续生成：补一句解释、给一个方案、把不完整过程整理成“已经完成”。真正稀缺的能力，是在事实没有闭合时停止迎合，并明确说“不”。</p><blockquote><p><strong>FCoP 协议的重要价值，是让 Agent 不只会回答“是”，还能够基于公共事实说“不”。</strong></p><p><strong>会生成答案并不稀缺；会拒绝把证据不足升级为“完成”，才是 Agent 的稀缺能力。</strong></p></blockquote><p>这个“不”不是情绪，也不是保守措辞，而是有实际后果的否决：不派 QA、不关闭任务、不制造重复任务、保留缺失证据，并让原任务继续。</p><p>WP-13 的核心不只是“另一个 Agent 发现了前一个 Agent 的错误”，而是协议和组织共同赋予 PM 一项稀缺能力：<strong>面对一个听起来完整的答案，仍然有依据拒绝它成为完成事实。</strong></p><h2 id="协议与应用边界-fcop-是-agent-posix-codeflowmu-是-runtime" tabindex="-1">协议与应用边界：FCoP 是 Agent POSIX，CodeFlowMu 是 Runtime <a class="header-anchor" href="#协议与应用边界-fcop-是-agent-posix-codeflowmu-是-runtime" aria-label="Permalink to &quot;协议与应用边界：FCoP 是 Agent POSIX，CodeFlowMu 是 Runtime&quot;">​</a></h2><p>这里集中说明一次二者的关系，后文不再重复展开。</p><h3 id="fcop-的全称是-filesystem-coordination-protocol" tabindex="-1">FCoP 的全称是 Filesystem Coordination Protocol <a class="header-anchor" href="#fcop-的全称是-filesystem-coordination-protocol" aria-label="Permalink to &quot;FCoP 的全称是 Filesystem Coordination Protocol&quot;">​</a></h3><p>“Filename as Protocol”不是 FCoP 的全称，而是它的核心不变量：<strong>文件名即协议</strong>。</p><p>FCoP 当前的核心表述是：</p><blockquote><p><strong>文件即协议；位置定义状态；事件记录历史。</strong></p><p><strong>Files carry protocol. Paths address state. Events replay transitions.</strong></p></blockquote><p>TASK 把“要做什么”外化，REPORT 把“做了什么”外化，REVIEW 把“谁依据什么作出判断”外化；文件位置表达当前状态，<code>transitions:</code> 只追加保存过去发生过的迁移。</p><h3 id="fcop-是行为治理协议层-不是幻觉检测器" tabindex="-1">FCoP 是行为治理协议层，不是幻觉检测器 <a class="header-anchor" href="#fcop-是行为治理协议层-不是幻觉检测器" aria-label="Permalink to &quot;FCoP 是行为治理协议层，不是幻觉检测器&quot;">​</a></h3><p>FCoP 不理解 WP-13 的业务目标，不运行测试，也不判断某条自然语言是否可信。它规定 Agent 如何报告行为、如何接受 Review、如何在能力边界内被审计。</p><h3 id="fcop-是-agent-posix-不是-agent-os" tabindex="-1">FCoP 是 Agent POSIX，不是 Agent OS <a class="header-anchor" href="#fcop-是-agent-posix-不是-agent-os" aria-label="Permalink to &quot;FCoP 是 Agent POSIX，不是 Agent OS&quot;">​</a></h3><table tabindex="0"><thead><tr><th>FCoP 负责</th><th>FCoP 不负责</th></tr></thead><tbody><tr><td>状态语义与合法迁移</td><td>调用 LLM、执行工具</td></tr><tr><td>TASK / REPORT / REVIEW 文件契约</td><td>唤醒 Agent、调度队列</td></tr><tr><td>行为事件的外化格式</td><td>自动重试、Heartbeat、TTL</td></tr><tr><td>审计与只追加历史</td><td>决定哪个 Agent 现在执行</td></tr><tr><td>能力声明与 Review 语义</td><td>沙箱、进程和权限强制的具体实现</td></tr></tbody></table><h3 id="codeflowmu-是-fcop-的应用现场" tabindex="-1">CodeFlowMu 是 FCoP 的应用现场 <a class="header-anchor" href="#codeflowmu-是-fcop-的应用现场" aria-label="Permalink to &quot;CodeFlowMu 是 FCoP 的应用现场&quot;">​</a></h3><p>CodeFlowMu 负责运行 PM、DEV、QA、OPS 等角色，维持任务身份，执行唤醒与调度，记录 Runtime 事件，展示实时操作流，并在异常后恢复原任务。</p><p>二者的关系可以压缩为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CodeFlowMu：Application / Runtime / Scheduler / UI</span></span>
<span class="line"><span>FCoP：Identity + Location + Event + Behavior Governance</span></span></code></pre></div><p>或者更直白地说：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CodeFlowMu：让事情发生</span></span>
<span class="line"><span>FCoP：让发生过的事情可以被报告、检查、审阅和追溯</span></span></code></pre></div><p>因此，WP-13 是一个 <strong>CodeFlowMu 应用案例</strong>，也是一份 <strong>FCoP 现场证据</strong>；它不是“FCoP 自动检测并修复幻觉”的案例。</p><h2 id="多-agent-的真正价值-是组织上的否决权" tabindex="-1">多 Agent 的真正价值，是组织上的否决权 <a class="header-anchor" href="#多-agent-的真正价值-是组织上的否决权" aria-label="Permalink to &quot;多 Agent 的真正价值，是组织上的否决权&quot;">​</a></h2><p>假设系统只是增加一个 Reviewer Agent，然后把 DEV 的答案转给它：</p><blockquote><p>DEV：任务完成了。</p><p>Reviewer：看起来合理，通过。</p></blockquote><p>这仍然不是团队，只是两个模型围绕同一段文本互相评价。</p><p>真正的角色分离至少需要三件事：</p><ol><li><strong>职责不同</strong>：DEV 交付，PM 裁决，QA 验证；</li><li><strong>事实来源不同</strong>：不能都只读同一份自然语言总结；</li><li><strong>权限不同</strong>：DEV 不能批准自己，QA 不能替 PM 改任务目标，Runtime 不能替业务角色作最终判断。</li></ol><p>所以，多 Agent 防幻觉的关键不是 Agent 数量，而是组织结构。</p><blockquote><p><strong>没有角色边界的多 Agent，只是多份回答；有角色、有事实源、有裁决权的多 Agent，才是一支团队。</strong></p></blockquote><h2 id="三种-成功-必须彻底分开" tabindex="-1">三种“成功”必须彻底分开 <a class="header-anchor" href="#三种-成功-必须彻底分开" aria-label="Permalink to &quot;三种“成功”必须彻底分开&quot;">​</a></h2><p>这个案例最值得记住的边界是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>模型生成的完成声明</span></span>
<span class="line"><span>        ≠</span></span>
<span class="line"><span>协议中的完成状态</span></span>
<span class="line"><span>        ≠</span></span>
<span class="line"><span>业务上的验收通过</span></span></code></pre></div><h3 id="工具调用结束-不等于工作完成" tabindex="-1">工具调用结束，不等于工作完成 <a class="header-anchor" href="#工具调用结束-不等于工作完成" aria-label="Permalink to &quot;工具调用结束，不等于工作完成&quot;">​</a></h3><p>工具返回 <code>completed</code>，最多说明某次调用生命周期结束。若没有退出状态，就仍然是 <code>unknown</code>。</p><h3 id="工作完成-不等于业务通过" tabindex="-1">工作完成，不等于业务通过 <a class="header-anchor" href="#工作完成-不等于业务通过" aria-label="Permalink to &quot;工作完成，不等于业务通过&quot;">​</a></h3><p>代码、commit、REPORT 和测试齐全，才能证明 DEV 形成了交付；是否接受，还需要 PM/QA 根据任务合同判断。</p><h3 id="协议状态-不替代业务判断" tabindex="-1">协议状态，不替代业务判断 <a class="header-anchor" href="#协议状态-不替代业务判断" aria-label="Permalink to &quot;协议状态，不替代业务判断&quot;">​</a></h3><p>FCoP 的路径是 NOW 真相，事件是 PAST 证据，但 <code>done</code> 也不能被偷换成“产品价值已经获得最终业务批准”。协议语义与业务权威必须分别保持精确。</p><h2 id="这个案例应该推动什么改进-先改-runtime-不要膨胀协议" tabindex="-1">这个案例应该推动什么改进？先改 Runtime，不要膨胀协议 <a class="header-anchor" href="#这个案例应该推动什么改进-先改-runtime-不要膨胀协议" aria-label="Permalink to &quot;这个案例应该推动什么改进？先改 Runtime，不要膨胀协议&quot;">​</a></h2><p>WP-13 首先暴露的是 CodeFlowMu Runtime 问题：</p><ul><li><code>no exit status</code> 应稳定保持为 <code>unknown</code>；</li><li>子执行完成与业务完成不能在界面上混为一谈；</li><li>任务应携带类型化证据合同；</li><li>Runtime 可以预计算 <code>report_missing</code>、<code>commit_unreachable</code>、<code>evidence_incomplete</code>；</li><li>PM 的事实裁决应形成轻量、不可变的记录；</li><li>QA 必须保持角色分离并真正重跑；</li><li>工具异常恢复后应优先续办原任务；</li><li>“completed 但无 exit status、commit、REPORT”的场景应进入回归测试。</li></ul><p>只有当多个独立 Runtime 都证明现有文件契约无法表达某种必要事实时，才应该讨论扩展 FCoP。否则，每遇到一次应用问题就增加字段、状态和自动判断，协议很快会从 Agent POSIX 膨胀成另一个 Agent OS。</p><h2 id="结尾-团队允许-agent-犯错-但不允许错误轻易通过" tabindex="-1">结尾：团队允许 Agent 犯错，但不允许错误轻易通过 <a class="header-anchor" href="#结尾-团队允许-agent-犯错-但不允许错误轻易通过" aria-label="Permalink to &quot;结尾：团队允许 Agent 犯错，但不允许错误轻易通过&quot;">​</a></h2><p>WP-13 最终通过了 27 项测试，但真正有价值的时刻发生在测试之前：一个 Agent 已经说“完成了”，系统却没有顺势把它包装成成功。</p><p>PM 查了事实，说“不”：子代理自称完成但产物不全，不能当真完成。</p><p>DEV 回到原任务，补齐真实交付；QA 重新验证，最后才给出 PASS。</p><p>如前所述，FCoP 负责公共事实面，CodeFlowMu 负责运行角色；真正完成否决动作的是拥有相应职责和权限的 PM。</p><blockquote><p><strong>单 Agent 的目标是尽可能答对。多 Agent 团队的目标，是即使有人答错，也不会让错误轻易成为组织事实。</strong></p></blockquote><p>幻觉不可避免，但它可以被限制在一次局部错误判断里，而不是扩散成一次错误交付。这才是多 Agent 最现实、也最有价值的“防幻觉”。</p><h2 id="彩蛋-这篇文章发布后-claude-又复现了一次同类错误" tabindex="-1">彩蛋：这篇文章发布后，Claude 又复现了一次同类错误 <a class="header-anchor" href="#彩蛋-这篇文章发布后-claude-又复现了一次同类错误" aria-label="Permalink to &quot;彩蛋：这篇文章发布后，Claude 又复现了一次同类错误&quot;">​</a></h2><p>这篇文章发布后，我把链接发给 Claude，让它继续审稿。我按它的修改意见更新并重新发布后，Claude 却连续判断“页面没有更新”。它反复调用同一个 <code>web_fetch</code> 路径，看到旧内容，就把结果进一步解释成“站点或 CDN 仍在返回旧版本”，并坚持每次调用都是一次新的网络请求。</p><p>问题不在于工具没有返回内容，而在于 Claude 把“工具调用完成”升级成了“返回内容就是最新事实”，又把同一个工具、同一个信息源的重复调用，当成了多次独立验证。</p><p>我随后在两台电脑上打开同一页面，看到的都是新版，并把截图发给它。到这一步，Claude 才承认：</p><blockquote><p><strong>我把“调用完成”直接当成了“结果就是最新事实”。</strong></p></blockquote><h3 id="四张现场截图-同一工具自证-直到独立观察介入" tabindex="-1">四张现场截图：同一工具自证，直到独立观察介入 <a class="header-anchor" href="#四张现场截图-同一工具自证-直到独立观察介入" aria-label="Permalink to &quot;四张现场截图：同一工具自证，直到独立观察介入&quot;">​</a></h3><p><strong>截图 1：Claude 坚持每次 <code>web_fetch</code> 都是“全新的、独立的网络请求”，并把六次相同结果解释为站点服务端或 CDN 返回旧版本。</strong></p><p><img src="`+t+'" alt="Claude 彩蛋截图 1：把重复抓取解释为独立网络请求"></p><p><strong>截图 2：在看到新版页面截图后，Claude 承认新版真实存在，但仍继续用“CDN 边缘节点不同步”解释自己的旧结果。</strong></p><p><img src="'+s+'" alt="Claude 彩蛋截图 2：承认新版存在后仍推断 CDN 边缘差异"></p><p><strong>截图 3：Claude 开始承认方法错误——它反复使用同一个工具、同一个信息源自证，没有像 PM 或 QA 那样主动切换到独立来源交叉核验。</strong></p><p><img src="'+o+'" alt="Claude 彩蛋截图 3：承认没有引入独立信息源"></p><p><strong>截图 4：在两台电脑都显示新版后，Claude 最终明确承认，它把“工具调用完成”直接当成了“结果就是最新事实”。</strong></p><p><img src="'+p+`" alt="Claude 彩蛋截图 4：承认把调用完成误当成最新事实"></p><p>这次错误可以压缩成三条边界：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>web_fetch completed</span></span>
<span class="line"><span>        ≠</span></span>
<span class="line"><span>返回页面就是最新事实</span></span>
<span class="line"><span></span></span>
<span class="line"><span>同一工具重复调用六次</span></span>
<span class="line"><span>        ≠</span></span>
<span class="line"><span>六个独立信息源</span></span>
<span class="line"><span></span></span>
<span class="line"><span>一个听起来合理的 CDN 解释</span></span>
<span class="line"><span>        ≠</span></span>
<span class="line"><span>已经被证明的根因</span></span></code></pre></div><p>这与 WP-13 的主案例是同一种治理问题。正文里，DEV 的 <code>completed</code> 不能覆盖磁盘、Git、REPORT 和测试事实；这个彩蛋里，Claude 的多次 <code>web_fetch</code> 也不能覆盖两台设备实际看到的新版页面。领域不同，错误结构相同：<strong>一个 Agent 可以提出结论，但这个结论不能靠同一条工具链反复自证，就自动晋升为事实。</strong></p><p>两台电脑的交叉确认不是外部第三方审计，但它至少引入了独立于 Claude 单一抓取路径的观察，足以迫使原结论重新接受核验。</p><p>这个彩蛋也保留自己的证据边界：它不证明旧内容的根因一定是 Claude 本地缓存、CDN 或某个边缘节点；它只证明，在根因尚未确定时，Claude 已经把单一抓取路径返回的旧内容升级成了确定结论，并继续用同一来源为自己背书。</p><blockquote><p><strong>最危险的不是工具返回了旧内容，而是 Agent 在没有独立证据时，对旧内容作出了过度确定的解释。</strong></p></blockquote><hr><h2 id="下载完整证据包" tabindex="-1">下载完整证据包 <a class="header-anchor" href="#下载完整证据包" aria-label="Permalink to &quot;下载完整证据包&quot;">​</a></h2><p>本文不是根据回忆重新编排的故事。WP-13 的原始 TASK、DEV/QA REPORT、Runtime JSONL、会话摘录、测试结果、commit patch、截图和校验清单已经整理为可离线审阅的证据包。</p><ul><li><a href="https://raw.githubusercontent.com/joinwell52-AI/joinwell52/main/docs/public/evidence/wp13-multi-agent-fact-checking/wp13-multi-agent-fact-check-publication-evidence-v3.zip" target="_blank" rel="noreferrer">下载 WP-13 多 Agent 事实复核证据包（ZIP）</a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/docs/public/evidence/wp13-multi-agent-fact-checking/wp13-multi-agent-fact-check-publication-evidence-v3.zip" target="_blank" rel="noreferrer">在 GitHub 中查看附件位置</a></li><li>SHA-256：<code>5b5eda3034c822f13421783244b1d0c76a9fa79950bfad0ce61bb8d2e404131c</code></li></ul><p>证据包用于复核本文陈述，不改变本文末尾的证据边界：它证明 DEV 后续形成真实交付并取得角色分离 QA PASS，但不证明外部第三方认证，也不把快照中的 <code>review / pending</code> 解释成最终业务批准。</p><h2 id="fcop-参考资料" tabindex="-1">FCoP 参考资料 <a class="header-anchor" href="#fcop-参考资料" aria-label="Permalink to &quot;FCoP 参考资料&quot;">​</a></h2><ul><li><a href="https://github.com/joinwell52-AI/FCoP" target="_blank" rel="noreferrer">FCoP 仓库：文件驱动的 Agent 协作协议</a></li><li><a href="https://github.com/joinwell52-AI/FCoP/blob/main/spec/fcop-v3-spec.zh.md" target="_blank" rel="noreferrer">FCoP v3 当前规范：文件即协议；位置定义状态；事件记录历史</a></li><li><a href="https://github.com/joinwell52-AI/FCoP/blob/main/adr/ADR-0029-fcop-behavior-governance-charter.md" target="_blank" rel="noreferrer">ADR-0029：FCoP 行为治理协议宪章</a></li><li><a href="https://github.com/joinwell52-AI/FCoP/blob/main/adr/ADR-0038-fcop-boundary-charter.md" target="_blank" rel="noreferrer">ADR-0038：FCoP Boundary Charter——Agent POSIX, not Agent OS</a></li><li><a href="https://github.com/joinwell52-AI/FCoP/blob/main/adr/ADR-0039-fcop-freeze-discipline-and-runtime-absorption-era.md" target="_blank" rel="noreferrer">ADR-0039：Runtime Absorption Era</a></li></ul><h2 id="证据边界" tabindex="-1">证据边界 <a class="header-anchor" href="#证据边界" aria-label="Permalink to &quot;证据边界&quot;">​</a></h2><p>本文基于 WP-13 出版证据包整理。案例证明 DEV 后续形成真实交付并取得角色分离 QA PASS；证据快照时 TASK-019/020 仍处于 <code>review / pending</code>，不据此宣称 PM 已完成最终批准或任务已终态关闭。QA 是角色分离验证，不是外部第三方认证。</p>`,145))])}const q=i(g,[["render",m]]);export{v as __pageData,q as default};
